                    String listMethod = switchReceiverMulti ? "mapItemToList" : "mapSingleToList";
                    return JavaExpression.from(
                            arg + CHAIN_LINK + listMethod + "(" + choiceListBlock.text() + ")",
                            null,
                            mergeRefs(argBuilder, choiceListBlock),
                            mergeStaticImports(argBuilder, choiceListBlock));
