    private static String renderDrainedHoists(
            java.util.List<com.regnosys.rosetta.generator.java.statement.JavaStatement> hoists,
            String indent, Set<JavaClass<?>> refs, Set<JavaClass<?>> wildcards) {
        if (hoists.isEmpty()) {
            return "";
        }
        StringBuilder out = new StringBuilder();
        for (com.regnosys.rosetta.generator.java.statement.JavaStatement hoist : hoists) {
            refs.addAll(hoist.getRefs());
            wildcards.addAll(hoist.getStaticWildcardImports());
            StringBuilder one = new StringBuilder();
            hoist.render(one);
            for (String line : one.toString().split("\n", -1)) {
                if (!line.isEmpty()) {
                    out.append(indent).append(line);
                }
            }
        }
        return out.toString();
    }

